import {SAMPLE} from './sample.js';
import {MAX_BYTES,parseSQL,updateColumn,addColumn,addTable,addRelation,editCell,removeColumn} from './sql-engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={sql:SAMPLE,model:null,selected:null,view:'diagram',positions:new Map(),zoom:1,pan:{x:0,y:0},page:0,history:[],future:[],valid:false,busy:false,request:0,committed:SAMPLE,filename:'loja_exemplo.sql',error:null};
let worker=null,pending=new Map(),debounce,timer,dialogAction=null;
try{worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{pending.get(data.id)?.resolve(data);pending.delete(data.id);};worker.onerror=()=>{worker?.terminate();worker=null;for(const [id,item] of pending){try{item.resolve({id,model:parseSQL(item.sql)});}catch(e){item.resolve({id,error:e.message,offset:e.offset});}}pending.clear();};}catch{}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,4200);}
function countLines(){const n=state.sql.split('\n').length;$('#line-numbers').textContent=Array.from({length:n},(_,i)=>i+1).join('\n');$('#code-meta').textContent=`${n} linhas · ${(new TextEncoder().encode(state.sql).length/1024).toFixed(1)} KB`;}
function parseAsync(sql,id){if(worker)return new Promise(resolve=>{pending.set(id,{resolve,sql});worker.postMessage({id,sql});});return new Promise(resolve=>setTimeout(()=>{try{resolve({id,model:parseSQL(sql)});}catch(e){resolve({id,error:e.message,offset:e.offset??0});}},0));}
function renderHistory(){$('#undo').disabled=state.busy||(!state.history.length&&state.sql===state.committed);$('#redo').disabled=state.busy||!state.future.length;$('#add-table').disabled=state.busy||!state.valid;$('#export').disabled=state.busy;}
async function synchronize(sql,{record=false,reset=false}={}){
  const id=++state.request;state.sql=sql;state.valid=false;state.busy=true;state.error=null;$('#sync-state').textContent='Atualizando…';renderHistory();if($('#sql-editor').value!==sql)$('#sql-editor').value=sql;countLines();
  const r=await parseAsync(sql,id);if(id!==state.request)return false;state.busy=false;state.error=r.error??null;
  if(r.error){$('#sync-state').textContent='Revisar SQL';showDiagnostics(r.error,r.offset);renderInspector();renderHistory();if(state.view==='data')renderData();return false;}
  if(record&&sql!==state.committed){state.history.push(state.committed);if(state.history.length>30)state.history.shift();state.future=[];}
  if(reset){state.history=[];state.future=[];state.positions.clear();state.selected=null;state.page=0;state.pan={x:0,y:0};}
  state.committed=sql;state.model=r.model;state.valid=true;if(!state.model.tables.some(t=>t.key===state.selected))state.selected=state.model.tables[0]?.key??null;$('#sync-state').textContent='Sincronizado';render();if(reset)requestAnimationFrame(initialFraming);return true;
}
function showDiagnostics(error,offset=0){const el=$('#diagnostics');el.classList.toggle('error',!!error);if(error){const line=state.sql.slice(0,offset).split('\n').length;el.innerHTML=`<strong>Linha ${line}: ${esc(error)}</strong><br>O último diagrama válido foi mantido. Revise no Código SQL; a edição visual fica pausada.`;el.hidden=false;}else{const ws=state.model?.warnings??[];el.hidden=!ws.length;el.innerHTML=ws.length?`<strong>Compatibilidade do arquivo</strong><ul>${ws.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:'';}}
const selected=()=>state.model?.tables.find(t=>t.key===state.selected);
function render(){renderHistory();showDiagnostics();renderList();renderStats();renderDiagram();if(state.view==='data')renderData();renderInspector();requestAnimationFrame(centerSelected);$('#selection-status').textContent=selected()?`${selected().name} · ${selected().columns.length} colunas`:'Nenhuma tabela definida';}
function renderList(){if(!state.model)return;const q=$('#search').value.toLowerCase();$('#table-count').textContent=state.model.tables.length;$('#table-list').innerHTML=state.model.tables.filter(t=>t.name.toLowerCase().includes(q)).map(t=>`<button class="table-item ${t.key===state.selected?'active':''}" data-table="${esc(t.key)}"><span class="table-icon">▦</span><span>${esc(t.name)}</span><span class="count">${t.columns.length}</span></button>`).join('')||'<p class="muted">Nenhuma tabela encontrada.</p>';}
function renderStats(){const m=state.model;$('#document-stats').innerHTML=`<div class="stat"><strong>${m.tables.length}</strong>tabelas</div><div class="stat"><strong>${m.relationCount}</strong>relações</div><div class="stat"><strong>${m.rowCount.toLocaleString('pt-BR')}</strong>registros</div>`;}
const nodeHeight=t=>46+Math.min(t.columns.length,30)*34+(t.columns.length>30?32:0)+33;
function layout(){const cols=Math.max(1,Math.min(3,Math.floor(($("#canvas").clientWidth-40)/310)));let y=40;for(let i=0;i<state.model.tables.length;i+=cols){let h=0;for(let j=i;j<Math.min(i+cols,state.model.tables.length);j++){const t=state.model.tables[j];if(!state.positions.has(t.key))state.positions.set(t.key,{x:35+(j%cols)*330,y});h=Math.max(h,nodeHeight(t));}y+=h+70;}}
function renderDiagram(){layout();const tables=state.model.tables.slice(0,150);if(selected()&&!tables.includes(selected()))tables.push(selected());$('#nodes').innerHTML=tables.map(t=>{const p=state.positions.get(t.key);return `<article class="node ${t.key===state.selected?'selected':''}" data-node="${esc(t.key)}" style="left:${p.x}px;top:${p.y}px"><div class="node-header" data-drag="${esc(t.key)}"><span class="entity-icon">▦</span><span class="node-name">${esc(t.name)}</span><span class="entity-count">${t.columns.length}</span></div>${t.columns.slice(0,30).map(c=>`<div class="column-row" data-column="${esc(c.key)}" title="${esc(c.name+' · '+c.type)}"><span class="column-key ${c.primary?'pk-symbol':t.relations.some(r=>r.columns.includes(c.name))?'fk-symbol':''}">${c.primary?'⚿':t.relations.some(r=>r.columns.includes(c.name))?'↗':'·'}</span><span class="column-name">${esc(c.name)}</span><span class="column-type">${esc(c.type)}</span></div>`).join('')}${t.columns.length>30?'<div class="node-footer">Mais colunas nas propriedades…</div>':''}<div class="node-footer">${t.name.includes('.')?esc(t.name.split('.').slice(0,-1).join('.')):'schema'}<span>${t.rows.length} registros</span></div></article>`;}).join('')+(tables.length?state.model.tables.length>150?'<div class="canvas-empty">Prévia de 150 tabelas. Selecione outras pelo explorador.</div>':'':'<div class="canvas-empty"><strong>Seu próximo esquema começa aqui.</strong><br>Importe um arquivo SQL ou crie uma tabela.</div>');drawRelations();transform();}
function drawRelations(){let html='<defs><marker id="rel-circle" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="5" markerHeight="5"><circle cx="5" cy="5" r="3.5" fill="#fff" stroke="#91a48f"/></marker></defs>';const visible=new Set([...document.querySelectorAll('[data-node]')].map(n=>n.dataset.node));for(const t of state.model.tables){if(!visible.has(t.key))continue;for(const r of t.relations){const target=state.model.tables.find(x=>x.key===r.targetKey);if(!target||!visible.has(target.key))continue;const a=state.positions.get(t.key),b=state.positions.get(target.key),right=a.x>=b.x,ac=Math.max(0,t.columns.findIndex(c=>r.columns.includes(c.name))),bc=Math.max(0,target.columns.findIndex(c=>r.targetColumns.includes(c.name)));const x1=a.x+(right?0:260),y1=a.y+46+Math.min(ac,29)*34+17,x2=b.x+(right?260:0),y2=b.y+46+Math.min(bc,29)*34+17,delta=Math.max(45,Math.abs(x2-x1)*.45),dir=right?-1:1;const path=t.key===target.key?`M ${a.x+260} ${y1} C ${a.x+310} ${y1},${a.x+310} ${y2},${a.x+260} ${y2}`:`M ${x1} ${y1} C ${x1+delta*dir} ${y1},${x2-delta*dir} ${y2},${x2} ${y2}`;html+=`<path class="relation ${t.key===state.selected||target.key===state.selected?'active':''}" d="${path}" marker-start="url(#rel-circle)" marker-end="url(#rel-circle)"><title>${esc(`${t.name}(${r.columns.join(', ')}) → ${r.target}(${r.targetColumns.join(', ')})`)}</title></path>`;}}$('#relations').innerHTML=html;}
function transform(){$('#world').style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${state.zoom})`;$('#zoom-label').textContent=Math.round(state.zoom*100)+'%';}
function zoom(amount){const rect=$('#canvas').getBoundingClientRect(),old=state.zoom;state.zoom=Math.min(1.8,Math.max(.15,state.zoom*amount));state.pan.x=rect.width/2-(rect.width/2-state.pan.x)*state.zoom/old;state.pan.y=rect.height/2-(rect.height/2-state.pan.y)*state.zoom/old;transform();}
function fit(){if(state.view!=='diagram'||!state.model)return;const rect=$('#canvas').getBoundingClientRect(),ts=state.model.tables.slice(0,150);if(!ts.length||rect.width<1)return;const xs=ts.map(t=>state.positions.get(t.key).x),ys=ts.map(t=>state.positions.get(t.key).y),minX=Math.min(...xs),minY=Math.min(...ys),maxX=Math.max(...xs)+260,maxY=Math.max(...ts.map(t=>state.positions.get(t.key).y+nodeHeight(t)));state.zoom=Math.min(1.1,Math.max(.15,Math.min((rect.width-70)/(maxX-minX),(rect.height-50)/(maxY-minY))));state.pan={x:(rect.width-(maxX-minX)*state.zoom)/2-minX*state.zoom,y:(rect.height-(maxY-minY)*state.zoom)/2-minY*state.zoom};transform();}
function initialFraming(){fit();if(state.zoom<.8){state.zoom=.95;state.pan={x:15,y:15};transform();}}
function centerSelected(){const t=selected();if(!t||state.view!=="diagram")return;const rect=$("#canvas").getBoundingClientRect(),p=state.positions.get(t.key);state.zoom=Math.max(.85,state.zoom);state.pan={x:Math.max(15,(rect.width-260*state.zoom)/2)-p.x*state.zoom,y:Math.max(20,(rect.height-nodeHeight(t)*state.zoom)/2)-p.y*state.zoom};transform();}
function choose(key,inspect=true){state.selected=key;state.page=0;renderList();renderDiagram();if(state.view==='data')renderData();$('.workspace').classList.toggle('inspecting',inspect);renderInspector();requestAnimationFrame(centerSelected);$('#selection-status').textContent=`${selected()?.name??''} · ${selected()?.columns.length??0} colunas`;}
function renderInspector(){const t=selected();if(!t){$('#inspector-content').innerHTML='<div class="inspector-body muted">Importe um arquivo ou crie uma tabela para começar.</div>';return;}if(!state.valid){$('#inspector-content').innerHTML='<div class="inspector-body muted">Revise o SQL antes de fazer alterações visuais.</div>';return;}$('#inspector-content').innerHTML=`<div class="inspector-body"><div class="eyebrow">TABELA</div><h2>${esc(t.name)}</h2><div class="muted">${t.columns.length} colunas · ${t.rows.length} registros</div><button class="button wide" data-action="table-code">&lt;/&gt; Editar no código</button><div class="property-section"><div class="section-label">COLUNAS</div>${t.columns.map(c=>`<div class="property-column"><span class="${c.primary?'pk-symbol':''}">${c.primary?'⚿':'·'}</span><span>${esc(c.name)}<small>${esc(c.type)}${c.nullable?' · NULL permitido':''}</small></span><button class="icon-button" data-edit-column="${esc(c.key)}" title="Editar coluna" aria-label="Editar ${esc(c.name)}">✎</button></div>`).join('')}<button class="button wide" data-action="add-column">＋ Nova coluna</button></div><div class="property-section"><div class="section-label">RELACIONAMENTOS</div>${t.relations.map(r=>`<div class="relation-item">${esc(r.columns.join(', '))} ↗<br><strong>${esc(r.target)}</strong> · ${esc(r.targetColumns.join(', '))}</div>`).join('')||'<p class="muted">Nenhuma chave estrangeira.</p>'}<button class="button wide" data-action="add-relation">＋ Relacionamento</button></div></div>`;}
function renderData(){const t=selected();$('#data-title').textContent=t?.name??'Nenhuma tabela';$('#data-count').textContent=t?`${t.rows.length.toLocaleString('pt-BR')} registros na prévia`:'';if(!t||!t.rows.length){$('#data-table').innerHTML='<div class="empty"><div><strong>Nenhum registro nesta tabela</strong><br>Adicione INSERT INTO … VALUES no Código SQL para visualizar dados.</div></div>';$('#pagination').innerHTML='';return;}const pages=Math.ceil(t.rows.length/50);state.page=Math.min(state.page,pages-1);const rows=t.rows.slice(state.page*50,state.page*50+50);$('#data-table').innerHTML=`<table><thead><tr>${t.columns.map(c=>`<th>${esc(c.name)}<small>${esc(c.type)}</small></th>`).join('')}</tr></thead><tbody>${rows.map((row,i)=>`<tr>${t.columns.map(c=>{const cell=row.cells.find(x=>x.key===c.key);return `<td><button data-cell-row="${state.page*50+i}" data-cell-col="${esc(c.key)}" ${!cell||!state.valid?'disabled':''} class="${cell?.value==null?'null-value':''}" title="${esc(cell?.raw??'Valor não fornecido neste INSERT')}">${cell?cell.value===null?'NULL':esc(cell.value):'—'}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table>`;$('#pagination').innerHTML=`<span>${state.page*50+1}–${Math.min((state.page+1)*50,t.rows.length)} de ${t.rows.length}</span><button class="button small" data-page="-1" ${state.page===0?'disabled':''}>Anterior</button><button class="button small" data-page="1" ${state.page===pages-1?'disabled':''}>Próxima</button>`;}
function view(name){if(!['diagram','data','code'].includes(name))return;state.view=name;for(const v of ['diagram','data','code'])$('#'+v+'-view').hidden=v!==name;document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===name));if(name==='data')renderData();if(name==='diagram')requestAnimationFrame(fit);}
function assertEditable(){if(state.busy||!state.valid||state.sql!==state.committed)throw Error('Aguarde a sincronização ou revise o SQL antes de editar visualmente.');}
async function commit(sql){assertEditable();const old=state.committed;if(!await synchronize(sql,{record:true})){const error=state.error;await synchronize(old);throw Error(error);}return true;}
function openModal(title,body,action){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-error').textContent='';$('#modal-actions').hidden=!action;dialogAction=action;$('#modal-form button[type="submit"]').textContent=title.startsWith("Substituir")?"Substituir arquivo":title.startsWith("Remover")?"Remover coluna":"Salvar alteração";$('#modal').showModal();}
const field=(label,name,value='',extra='')=>`<label class="form-field">${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;
function columnModal(name=null){try{assertEditable();const table=selected();if(!table)throw Error('Selecione uma tabela.');const c=table.columns.find(c=>c.key===name);openModal(c?`Editar ${c.name}`:'Nova coluna',`${field('Nome','name',c?.name??'',c?'readonly':'required maxlength="80"')}${field('Tipo SQL','type',c?.type??'VARCHAR(100)','required maxlength="120"')}<label class="checkbox"><input name="primary" type="checkbox" ${c?.primary?'checked':''} ${c?.tablePrimary?'disabled':''}> Chave primária</label><label class="checkbox"><input name="nullable" type="checkbox" ${!c||c.nullable?'checked':''}> Permitir NULL</label><p class="modal-help">${c?'Altere nomes no código para revisar suas dependências.':'Tabelas com INSERTs devem ser ampliadas pelo código para ajustar seus valores.'}</p>${c?'<button type="button" id="remove-column" class="text-button danger">Remover coluna…</button>':''}`,async form=>{const primary=c?.tablePrimary?c.primary:form.has('primary'),nullable=primary?false:form.has('nullable');const sql=c?updateColumn(state.sql,table,c,{type:form.get('type'),primary,nullable}):addColumn(state.sql,table,{name:form.get('name'),type:form.get('type'),primary,nullable});await commit(sql);toast(c?'Coluna atualizada no SQL.':'Coluna adicionada ao SQL.');});const check=$('#modal-body input[name="primary"]'),nullCheck=$('#modal-body input[name="nullable"]');const syncNull=()=>{if(check.checked)nullCheck.checked=false;nullCheck.disabled=check.checked;};check.addEventListener('change',syncNull);syncNull();if(c)$('#remove-column').onclick=()=>{try{const proposed=removeColumn(state.sql,state.model,table,c);openModal(`Remover ${c.name}?`,'<p class="modal-help">A definição será removida do SQL. Você poderá desfazer a alteração.</p>',async()=>{await commit(proposed);toast('Coluna removida.');});}catch(e){$('#modal-error').textContent=e.message;}};}catch(e){toast(e.message);}}
function tableModal(){try{assertEditable();openModal('Nova tabela',`${field('Nome da tabela','name','','required maxlength="80"')}<p class="modal-help">A tabela começa com id INTEGER PRIMARY KEY. Adicione outras colunas nas propriedades.</p>`,async form=>{const name=form.get('name');await commit(addTable(state.sql,name));choose(name.toLowerCase());toast('Tabela criada no SQL.');});}catch(e){toast(e.message);}}
function relationModal(){try{assertEditable();const t=selected();if(!t)throw Error('Selecione uma tabela.');openModal('Novo relacionamento',`<label class="form-field">Coluna em ${esc(t.name)}<select name="source">${t.columns.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}</option>`).join('')}</select></label><label class="form-field">Tabela de destino<select name="target">${state.model.tables.map(x=>`<option value="${esc(x.key)}">${esc(x.name)}</option>`).join('')}</select></label><label class="form-field">Coluna de destino<select name="targetColumn"></select></label><p class="modal-help">A referência será adicionada como FOREIGN KEY. Escolha uma coluna de destino com PRIMARY KEY ou UNIQUE.</p>`,async form=>{const target=state.model.tables.find(t=>t.key===form.get('target'));await commit(addRelation(state.sql,t,form.get('source'),target,form.get('targetColumn')));toast('Relacionamento adicionado ao SQL.');});const target=$('#modal-body select[name="target"]');const refresh=()=>{const table=state.model.tables.find(t=>t.key===target.value);$('#modal-body select[name="targetColumn"]').innerHTML=table.columns.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}${c.primary?' · PK':c.unique?' · UNIQUE':''}</option>`).join('');};target.onchange=refresh;refresh();}catch(e){toast(e.message);}}
function cellModal(row,col){try{assertEditable();const t=selected(),cell=t.rows[row]?.cells.find(c=>c.key===col);if(!cell)return;openModal(`Editar ${t.name}.${cell.column}`,`${field('Valor como literal SQL','value',cell.raw,'required')}<p class="modal-help">Texto: 'Ana Souza' · número: 123.45 · booleano: TRUE · vazio: NULL. Para uma aspa no texto, use duas: 'D''Ávila'.</p>`,async form=>{await commit(editCell(state.sql,cell,form.get('value')));toast('Valor atualizado no INSERT original.');});}catch(e){toast(e.message);}}
async function undo(){clearTimeout(debounce);if(state.sql!==state.committed){state.future.push(state.sql);await synchronize(state.committed);return;}if(!state.history.length)return;state.future.push(state.committed);await synchronize(state.history.pop());}
async function redo(){clearTimeout(debounce);if(!state.future.length)return;state.history.push(state.committed);await synchronize(state.future.pop());}
function exportSQL(){const blob=new Blob([state.sql],{type:'application/sql;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=state.filename.endsWith('.sql')?state.filename:state.filename+'.sql';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('SQL exportado.');}
function confirmReplace(action){if(state.sql===SAMPLE&&state.history.length===0){action();return;}openModal('Substituir o arquivo atual?','<p class="modal-help">Exporte seu SQL para manter as alterações antes de abrir outro arquivo.</p>',async()=>{await action();});}
async function importFile(file){if(!file)return;if(file.size>MAX_BYTES){toast('O limite desta versão é 5 MB por arquivo.');return;}if(!/\.sql$/i.test(file.name)){toast('Selecione um arquivo com extensão .sql.');return;}const sql=await file.text();confirmReplace(async()=>{clearTimeout(debounce);const old=state.committed;state.filename=file.name;$('#filename').textContent=file.name;if(await synchronize(sql,{reset:true})){view('diagram');toast('SQL importado.');}else{view('code');toast('Arquivo aberto no editor. Revise os avisos para ativar a edição visual.');state.history=[old];state.future=[];renderHistory();}});}
$('#import').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{await importFile(e.target.files[0]);e.target.value='';};$('#export').onclick=exportSQL;$('#add-table').onclick=tableModal;$('#undo').onclick=undo;$('#redo').onclick=redo;$('#search').oninput=renderList;$('#fit').onclick=fit;$('#arrange').onclick=()=>{state.positions.clear();renderDiagram();fit();};$('#zoom-in').onclick=()=>zoom(1.15);$('#zoom-out').onclick=()=>zoom(1/1.15);$('#close-inspector').onclick=()=>$('.workspace').classList.remove('inspecting');
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('#table-list').onclick=e=>{const b=e.target.closest('[data-table]');if(b)choose(b.dataset.table,state.view!=='data');};
$('#inspector-content').onclick=e=>{const c=e.target.closest('[data-edit-column]');if(c){columnModal(c.dataset.editColumn);return;}const a=e.target.closest('[data-action]');if(!a)return;if(a.dataset.action==='add-column')columnModal();if(a.dataset.action==='add-relation')relationModal();if(a.dataset.action==='table-code'){view('code');const t=selected();$('#sql-editor').focus();$('#sql-editor').setSelectionRange(t.nameStart,t.nameEnd);$('#sql-editor').scrollTop=Math.max(0,(state.sql.slice(0,t.nameStart).split('\n').length-4)*23.4);}};
$('#data-table').onclick=e=>{const b=e.target.closest('[data-cell-row]');if(b)cellModal(Number(b.dataset.cellRow),b.dataset.cellCol);};$('#pagination').onclick=e=>{const b=e.target.closest('[data-page]');if(b){state.page+=Number(b.dataset.page);renderData();}};
$('#modal-form').onsubmit=async e=>{e.preventDefault();if(!dialogAction)return;const action=dialogAction,button=$('#modal-form button[type="submit"]');button.disabled=true;try{await action(new FormData(e.currentTarget));$('#modal').close();}catch(err){$('#modal-error').textContent=err.message;}finally{button.disabled=false;}};$('#modal-close').onclick=$('#modal-cancel').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>{dialogAction=null;});
$('#sql-editor').oninput=e=>{state.sql=e.target.value;state.valid=false;state.request++;state.busy=true;$('#sync-state').textContent='Atualizando…';countLines();renderHistory();renderInspector();clearTimeout(debounce);debounce=setTimeout(()=>synchronize(state.sql,{record:true}),450);};$('#sql-editor').onscroll=e=>$('#line-numbers').scrollTop=e.target.scrollTop;$('#apply-code').onclick=()=>{clearTimeout(debounce);synchronize($('#sql-editor').value,{record:true});};$('#sql-editor').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const el=e.currentTarget;el.setRangeText('  ',el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input'));}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('#apply-code').click();}};
$('#example').onclick=()=>confirmReplace(async()=>{clearTimeout(debounce);state.filename='loja_exemplo.sql';$('#filename').textContent=state.filename;await synchronize(SAMPLE,{reset:true});view('diagram');});
$('#help').onclick=()=>openModal('Como usar o SQL Atlas',`<div class="help-content"><p>Importe um .sql ou edite o exemplo. Selecione uma tabela para modificar tipos, chaves e nulabilidade. Arraste as tabelas para organizar o diagrama.</p><ul><li><strong>Código ↔ visual:</strong> sincronização automática. SQL incompleto pausa a edição visual e mantém o último diagrama válido.</li><li><strong>Dados:</strong> a grade lê INSERT INTO … VALUES e edita os literais originais. São 50 linhas por página, até 20.000 por tabela.</li><li><strong>Compatibilidade:</strong> CREATE TABLE, tipos comuns, nomes com aspas, PK/FK compostas e ALTER TABLE ADD de chaves. Views, triggers, consultas, UPDATE, DELETE, COPY, ALTER de colunas e recursos de dialetos ficam no código; não são executados.</li><li><strong>Limites:</strong> arquivos UTF-8 de até 5 MB; até 150 tabelas simultâneas no diagrama. Selecione outras no explorador.</li><li><strong>Salvar:</strong> exporte o .sql. O arquivo fica na memória desta aba; recarregar descarta alterações. A posição do diagrama não altera o SQL.</li></ul><p>Referências: <a href="https://www.postgresql.org/docs/18/sql-createtable.html" target="_blank" rel="noreferrer">PostgreSQL CREATE TABLE</a> e <a href="https://www.sqlite.org/lang_insert.html" target="_blank" rel="noreferrer">SQLite INSERT</a>.</p></div>`,null);
let drag=null;$('#canvas').onpointerdown=e=>{if(e.button!==0)return;const header=e.target.closest('[data-drag]'),node=e.target.closest('[data-node]');if(header)drag={key:header.dataset.drag,x:e.clientX,y:e.clientY,base:{...state.positions.get(header.dataset.drag)},moved:false};else if(!node)drag={key:null,x:e.clientX,y:e.clientY,base:{...state.pan},moved:false};else return;$('#canvas').setPointerCapture(e.pointerId);};$('#canvas').onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(drag.key){const p={x:Math.max(0,drag.base.x+dx/state.zoom),y:Math.max(0,drag.base.y+dy/state.zoom)};state.positions.set(drag.key,p);const n=[...document.querySelectorAll('[data-node]')].find(n=>n.dataset.node===drag.key);if(n){n.style.left=p.x+'px';n.style.top=p.y+'px';}drawRelations();}else{state.pan={x:drag.base.x+dx,y:drag.base.y+dy};transform();}};$('#canvas').onpointerup=e=>{if(drag?.key&&!drag.moved)choose(drag.key);drag=null;if($('#canvas').hasPointerCapture(e.pointerId))$('#canvas').releasePointerCapture(e.pointerId);};$('#canvas').onpointercancel=()=>drag=null;$('#nodes').ondblclick=e=>{const n=e.target.closest('[data-node]'),c=e.target.closest('[data-column]');if(n&&c){choose(n.dataset.node);columnModal(c.dataset.column);}};$('#nodes').onclick=e=>{if(e.target.closest('[data-drag]'))return;const n=e.target.closest('[data-node]');if(n)choose(n.dataset.node);};$('#canvas').addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey||e.metaKey)zoom(e.deltaY<0?1.08:1/1.08);else{state.pan.x-=e.deltaX;state.pan.y-=e.deltaY;transform();}},{passive:false});
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});document.addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();importFile(e.dataTransfer.files[0]);}});window.addEventListener('beforeunload',e=>{if(state.sql!==SAMPLE){e.preventDefault();e.returnValue='';}});window.addEventListener('resize',()=>{if(state.view==='diagram')fit();});
async function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});const tools=[{name:'read_sql_schema',description:'Read parsed tables and relationships without changing the document.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(input&&Object.keys(input).length)throw Error('No parameters accepted.');return {valid:state.valid,tables:state.model?.tables.map(t=>({name:t.name,columns:t.columns.map(c=>({name:c.name,type:c.type,primary:c.primary,nullable:c.nullable})),relationships:t.relations.map(r=>({columns:r.columns,target:r.target,targetColumns:r.targetColumns}))}))??[]};}},{name:'navigate_sql_table',description:'Select a table and open its diagram properties without changing the SQL.',inputSchema:{type:'object',properties:{name:{type:'string'}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(typeof input?.name!=='string'||Object.keys(input).some(k=>k!=='name'))throw Error('A table name is required.');const table=state.model?.tables.find(t=>t.name===input.name);if(!table)throw Error('Table not found.');view('diagram');choose(table.key);return {selected:table.name};}}];for(const tool of tools){try{await context.registerTool(tool,{signal:controller.signal});}catch{}}}
await synchronize(SAMPLE,{reset:true});registerTools();
